def calculate(op, *args):
    if op == 'add':
        return sum(args)
    elif op == 'mul':
        res = 1
        for x in args:
            res *= x
        return res

parts = input().split()
op = parts[0]
nums = list(map(int, parts[1:]))
print(calculate(op, *nums))

def merge(**kwargs):
    d = {}
    for k, v in kwargs.items():
        d[k] = d.get(k, 0) + v
    for k in d:
        print(f"{k}:{d[k]}", end=' ')

parts = input().split()
