def bs(arr, l, r, x):
    if l > r:
        return False
    m = (l + r) // 2
    if arr[m] == x:
        return True
    elif arr[m] > x:
        return bs(arr, l, m-1, x)
    else:
        return bs(arr, m+1, r, x)

n = int(input())
arr = list(map(int, input().split()))
x = int(input())
print("Found" if bs(arr, 0, n-1, x) else "Not Found")

def rev(s):
    if len(s) == 0:
        return s
    return rev(s[1:]) + s[0]

